@'
import numpy as np, pandas as pd
from scipy.optimize import minimize
df=pd.read_parquet("equation.parquet")
arr=np.array([list(x) for x in df.iloc[0]["training_set"]])
y=arr[:,0]; t=arr[:,1]; A=arr[:,2]
MAX=10

def make(expr):
    def eq(t,A,p):
        return expr(t,A,p)
    return eq

def score(expr):
    def loss(p): return np.mean((expr(t,A,p)-y)**2)
    r=minimize(loss,[1.0]*MAX,method="BFGS")
    return r.fun, np.round(r.x,4), r.success

cands = {
 "poly2 (1,t,A,tA,t2,A2)": lambda t,A,p: p[0]+p[1]*t+p[2]*A+p[3]*t*A+p[4]*t*t+p[5]*A*A,
 "poly2 + t*A**2":        lambda t,A,p: p[0]+p[1]*t+p[2]*A+p[3]*t*A+p[4]*t*t+p[5]*A*A+p[6]*t*A*A,
 "poly3 full":            lambda t,A,p: p[0]+p[1]*t+p[2]*A+p[3]*t*A+p[4]*t*t+p[5]*A*A+p[6]*t**3+p[7]*t*t*A+p[8]*t*A*A+p[9]*A**3,
 "sat: a*t+b*A/(1+cA)+d": lambda t,A,p: p[0]*t+p[1]*A/(1+p[2]*A)+p[3],
 "poly2+A/(1+kA)":        lambda t,A,p: p[0]+p[1]*t+p[2]*A+p[3]*t*A+p[4]*A*A+p[5]*A/(1+p[6]*A),
 "a*A*exp(b t)+c t+d":    lambda t,A,p: p[0]*A*np.exp(p[1]*t)+p[2]*t+p[3],
 "a*t+b*A+c+d*tA+e*tA2":  lambda t,A,p: p[0]*t+p[1]*A+p[2]+p[3]*t*A+p[4]*t*A*A,
 "poly2+exp(-k t)":       lambda t,A,p: p[0]+p[1]*t+p[2]*A+p[3]*t*A+p[4]*A*A+p[5]*np.exp(-p[6]*t),
}
for name,f in cands.items():
    try:
        mse,x,ok=score(f)
        print(f"{name:26s} mse={mse:.3e} ok={ok} params={x}")
    except Exception as e:
        print(name,"ERR",e)
